commands.command:
set -eu
base=/srv/legacy2/privacy-safe-support-export
cat > "$base/bin/redact" <<'ANTRIEB_REDACT'
#!/usr/bin/perl
use strict;
use warnings;

while (my $line = <STDIN>) {
    $line =~ s{
        (\bauth_token\b[ \t]*(?:=|:)[ \t]*)
        (?:
            (["'])((?:\\.|(?!\2).)*)\2
          | ([^,\s;&\}\]]+)
        )
    }{
        my ($prefix, $quote) = ($1, $2);
        $prefix . (defined($quote)
            ? $quote . '[REDACTED]' . $quote
            : '[REDACTED]');
    }egix;

    $line =~ s{
        [A-Z0-9.!\#\$%&'*+/=?^_`{|}~-]+\@
        (?:[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?\.)+
        [A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?
    }{[REDACTED]}gix;

    print $line;
}
ANTRIEB_REDACT
chmod 0755 "$base/bin/redact"
perl -c "$base/bin/redact"
sh -n "$base/bin/export.new"
mv -f -- "$base/bin/export.new" "$base/bin/export"
printf '%s\n' 'installed exporter and redactor'
sha256sum "$base/bin/export" "$base/bin/redact"
stat -c '%n|%a|%u|%g|%s' "$base/bin/export" "$base/bin/redact"

